// helper 回报失败原因。均为瞬态文件，成功或超时后清理。
const LOGIN_HELPER_FILE = join(CRED_DIR, 'login-helper.json');
const LOGIN_CONFIG_FILE = join(CRED_DIR, 'login-config.json');
const LOGIN_ERROR_FILE = join(CRED_DIR, 'login-error.json');

